from pptx import Presentation

prs = Presentation('BMW_1502_Presentation.pptx')

# Check all source references
for i, slide in enumerate(prs.slides):
    has_ref = False
    for shape in slide.shapes:
        if shape.has_text_frame:
            for para in shape.text_frame.paragraphs:
                t = para.text.strip()
                if 'Source:' in t:
                    print(f"Slide {i+1}: {t}")
                    has_ref = True
    if not has_ref:
        print(f"Slide {i+1}: NO SOURCE REFERENCE")

# Check image count
total_images = 0
for s in prs.slides:
    for shape in s.shapes:
        if shape.shape_type == 13:
            total_images += 1
print(f"\nTotal images: {total_images}")

# Check bullet count per slide
print("\nBullet points per slide:")
